CREATE TABLE t1(x INT, y INT); WITH RECURSIVE c(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM c WHERE i<32) INSERT INTO t1 SELECT 32-i, CASE WHEN i=1 THEN 10 WHEN i<=2 THEN 9 WHEN i<=4 THEN 8 WHEN i<=8 THEN 7 WHEN i<=16 THEN 6 ELSE 5 END FROM c ORDER BY i; CREATE TABLE t5(x,y); INSERT INTO t5 SELECT x-y, x+y FROM t1 WHERE x ORDER BY x DESC LIMIT 31;